const crypto = require('crypto');
const payload = $json.body;
const allowed = new Set(['sast.critical_new','sast.high_new','dependencies.critical_with_fix','dependencies.high_with_fix']);
if (!payload || payload.schemaVersion !== 1 || !Array.isArray(payload.findings) || payload.findings.length === 0) throw new Error('invalid or empty finding payload');
if (!payload.findings.every(f => f.action === 'BLOCK' && allowed.has(f.policyRule))) throw new Error('payload contains a non-overridable finding');
if (!/^[a-f0-9]{64}$/i.test(payload.gateDigest || '')) throw new Error('invalid gate digest');
if (!payload.context?.repository?.includes('/') || !/^\d+$/.test(String(payload.context.pullRequest || ''))) throw new Error('repository and pull request are required');
const timeout = Math.min(Math.max(Number(payload.timeoutSeconds) || 900, 60), 3600);
const now = new Date();
const requestId = crypto.randomUUID();
const request = { requestId, gateDigest: payload.gateDigest, status: 'pending', createdAt: now.toISOString(), expiresAt: new Date(now.getTime() + timeout * 1000).toISOString(), context: payload.context, findings: payload.findings };
const state = $getWorkflowStaticData('global');
state.requests ||= {};
state.requests[requestId] = request;
const lines = payload.findings.map(f => `• ${f.policyRule}: ${f.id} — ${f.reason}`);
return [{json:{request,discordMessage:{allowed_mentions:{parse:[]},embeds:[{title:'Break-glass security exception requested',description:lines.join('\n').slice(0,4000),color:15105570,fields:[{name:'Repository',value:payload.context.repository,inline:true},{name:'Pull request',value:`#${payload.context.pullRequest}`,inline:true},{name:'Commit',value:payload.context.commitSha.slice(0,12),inline:true},{name:'Expires',value:request.expiresAt}]}],components:[{type:1,components:[{type:2,style:3,label:'Approve',custom_id:`breakglass:${requestId}:approve`},{type:2,style:4,label:'Deny',custom_id:`breakglass:${requestId}:deny`}]}]}}}];

const prepared = $('Validate and Store Pending Request').first().json;
if (!$json.id) throw new Error('Discord did not return a message ID');
const state = $getWorkflowStaticData('global');
const request = state.requests?.[prepared.request.requestId];
if (!request || request.status !== 'pending') throw new Error('pending request disappeared');
request.discord = { channelId: '1545363889435451453', messageId: String($json.id) };
return [{json:{requestId:request.requestId,status:request.status,createdAt:request.createdAt,expiresAt:request.expiresAt}}];

const requestId = String($json.query?.requestId || '');
const state = $getWorkflowStaticData('global');
const request = state.requests?.[requestId];
if (!request) return [{json:{responseCode:404,responseBody:{error:'unknown_request'}}}];
if (request.status === 'pending' && new Date(request.expiresAt) <= new Date()) request.status = 'expired';
return [{json:{responseCode:200,responseBody:{requestId:request.requestId,gateDigest:request.gateDigest,status:request.status,createdAt:request.createdAt,expiresAt:request.expiresAt,decidedAt:request.decidedAt || null,approver:request.approver || null}}}];

const crypto = require('crypto');
const item = $input.first();
const headers = Object.fromEntries(Object.entries(item.json.headers || {}).map(([k,v]) => [k.toLowerCase(),String(v)]));
let rawBody;
const encoded = item.binary?.data?.data;
if (typeof encoded === 'string') rawBody = Buffer.from(encoded, 'base64');
if (!rawBody) { try { rawBody = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch {} }
const signatureHex = headers['x-signature-ed25519'];
const timestamp = headers['x-signature-timestamp'];
const publicKeyHex = '7e0f70984cec02d0ab25fd17567206210e9a395073e6e7ae316fe7078adb5cb8';
let verified = false;
try {
  if (!rawBody || !/^[0-9a-f]{64}$/i.test(publicKeyHex) || !/^[0-9a-f]{128}$/i.test(signatureHex || '') || !timestamp) throw new Error('missing signature material');
  if (!/^\d+$/.test(timestamp) || Math.abs(Math.floor(Date.now()/1000) - Number(timestamp)) > 300) throw new Error('stale or malformed timestamp');
  const key = crypto.createPublicKey({key:{kty:'OKP',crv:'Ed25519',x:Buffer.from(publicKeyHex,'hex').toString('base64url')},format:'jwk'});
  verified = crypto.verify(null,Buffer.concat([Buffer.from(timestamp,'utf8'),rawBody]),key,Buffer.from(signatureHex,'hex'));
} catch { verified = false; }
if (!verified) return [{json:{responseCode:401,responseBody:{error:'invalid_request_signature'},processComponent:false}}];
let interaction;
try { interaction = JSON.parse(rawBody.toString('utf8')); } catch { return [{json:{responseCode:400,responseBody:{error:'invalid_json'},processComponent:false}}]; }
if (interaction.type === 1) return [{json:{responseCode:200,responseBody:{type:1},processComponent:false}}];
if (interaction.type === 3) return [{json:{responseCode:200,responseBody:{type:6},processComponent:true,interaction}}];
return [{json:{responseCode:400,responseBody:{error:'unsupported_interaction'},processComponent:false}}];

const interaction = $json.interaction;
const match = /^breakglass:([0-9a-f-]{36}):(approve|deny)$/.exec(interaction.data?.custom_id || '');
if (!match) return [{json:{outcome:'rejected',interaction,message:'Invalid or stale approval control.'}}];
const [,requestId,action] = match;
const user = interaction.member?.user || interaction.user;
if (!user?.id) return [{json:{outcome:'rejected',interaction,message:'Discord did not provide a user identity.'}}];
const allowed = new Set(String($env.DISCORD_APPROVER_IDS || '').split(',').map(v=>v.trim()).filter(Boolean));
if (!allowed.has(String(user.id))) return [{json:{outcome:'unauthorized',interaction,requestId,message:`${user.username || user.id} is not an authorized break-glass approver.`}}];
const state = $getWorkflowStaticData('global');
const request = state.requests?.[requestId];
if (!request) return [{json:{outcome:'rejected',interaction,requestId,message:'Unknown approval request.'}}];
if (new Date(request.expiresAt) <= new Date()) { if (request.status === 'pending') request.status='expired'; return [{json:{outcome:'rejected',interaction,requestId,message:'This approval request has expired.'}}]; }
if (request.status !== 'pending') return [{json:{outcome:'duplicate',interaction,requestId,message:`Request is already ${request.status}.`}}];
request.status='processing';
request.claim={decision:action==='approve'?'approved':'denied',userId:String(user.id),username:user.global_name || user.username || String(user.id),claimedAt:new Date().toISOString()};
const findingText=request.findings.map(f=>`${f.policyRule}: ${f.id}`).join('; ');
const comment=`Break-glass decision: **${request.claim.decision.toUpperCase()}**\n\nVerified Discord approver: **${request.claim.username}** (ID: \`${request.claim.userId}\`)\n\nTimestamp: ${request.claim.claimedAt}\n\nOverridden finding(s): ${findingText}\n\nGate digest: \`${request.gateDigest}\``;
const disabled={allowed_mentions:{parse:[]},embeds:[{title:`Break-glass ${request.claim.decision}`,description:`Decision by ${request.claim.username} (${request.claim.userId})\n${findingText}`.slice(0,4000),color:request.claim.decision==='approved'?5763719:15548997}],components:[{type:1,components:[{type:2,style:3,label:'Approve',custom_id:`breakglass:${requestId}:approve`,disabled:true},{type:2,style:4,label:'Deny',custom_id:`breakglass:${requestId}:deny`,disabled:true}]}]};
return [{json:{outcome:'claimed',interaction,requestId,request,githubComment:comment,discordUpdate:disabled}}];

const claimed = $('Authorize and Claim Decision').first().json;
const state = $getWorkflowStaticData('global');
const request = state.requests?.[claimed.requestId];
if (!request || request.status !== 'processing' || request.claim?.userId !== claimed.request.claim.userId) throw new Error('decision claim changed before finalization');
request.status=request.claim.decision;
request.decidedAt=new Date().toISOString();
request.approver={id:request.claim.userId,username:request.claim.username};
delete request.claim;
return [{json:{requestId:request.requestId,status:request.status}}];

